export const trophiesData=[{id:"ranji-trophy",trophy:"Ranji Trophy",sport:"Cricket",category:"Cricket",namesake:"Maharaja Sir Ranjitsinhji Vibhaji II ('Ranji')",namesakeCategory:"Royalty & Pioneers",yearInstituted:1934,tournament:"Premier Domestic First-Class Cricket Championship of India",historicalBackground:"Maharaja Sir Ranjitsinhji Vibhaji II (1872–1933), Jam Saheb of Nawanagar (present-day Jamnagar, Gujarat), was the first Indian to play international Test cricket (representing England). Known for his revolutionary leg-glance shot and dazzling batting style, Ranji scored 24,692 first-class runs with 72 centuries. After retiring, he served as a distinguished ruler, diplomat, and Chancellor of the Indian Chamber of Princes.",significance:"Donated by Maharaja Bhupinder Singh of Patiala in 1934 to honor Ranji after his passing. The Ranji Trophy remains the backbone of Indian cricket, serving as the primary pathway for selecting the Indian national Test team.",icon:"🏏",accentColor:"linear-gradient(135deg, #b45309, #d97706)"},{id:"durand-cup",trophy:"Durand Cup",sport:"Football",category:"Football",namesake:"Sir Henry Mortimer Durand",namesakeCategory:"British India Administration",yearInstituted:1888,tournament:"Durand Football Tournament (Oldest in Asia)",historicalBackground:"Sir Henry Mortimer Durand (1850–1924) was Foreign Secretary of British India from 1884 to 1894. He is famous in geopolitical history for establishing the Durand Line, the international border boundary between modern-day Afghanistan and Pakistan. An avid sports enthusiast while recovering from illness in Shimla, he founded the tournament to promote physical health among armed forces.",significance:"First played at Dagshai (Shimla) in 1888, the Durand Cup is the oldest football tournament in Asia and the 3rd oldest existing football competition in the world (after the FA Cup and Scottish Cup). Today, it features India's top ISL, I-League, and Armed Forces clubs.",icon:"⚽",accentColor:"linear-gradient(135deg, #1e3a8a, #2563eb)"},{id:"dhyan-chand-khel-ratna",trophy:"Major Dhyan Chand Khel Ratna Award",sport:"Multi-Sport",category:"Multi-Sport",namesake:"Major Dhyan Chand ('The Wizard')",namesakeCategory:"Sports Legends",yearInstituted:1991,renamedYear:2021,tournament:"Republic of India National Sports Awards (Highest Sporting Honor)",historicalBackground:"Major Dhyan Chand Bais (1905–1979) was an Indian Army soldier and the greatest field hockey player in history. Playing as center-forward, he led India to 3 consecutive Olympic Gold Medals in Amsterdam 1928, Los Angeles 1932, and Berlin 1936, scoring over 400 international goals. His supreme ball control earned him the title 'The Wizard' (Hockey ka Jaadugar). August 29, his birthday, is celebrated as India's National Sports Day.",significance:"India's highest national sporting award presented annually by the President of India at Rashtrapati Bhavan. Renamed in 2021 in honor of Dhyan Chand, it recognizes spectacular and most outstanding performance by a sportsperson over four years.",icon:"🏑",accentColor:"linear-gradient(135deg, #15803d, #16a34a)"},{id:"santosh-trophy",trophy:"Santosh Trophy",sport:"Football",category:"Football",namesake:"Sir Manmatha Nath Roy Chowdhury (Maharaja of Santosh)",namesakeCategory:"Royalty & Administrators",yearInstituted:1941,tournament:"Senior National Football Championship of India",historicalBackground:"Sir Manmatha Nath Roy Chowdhury (1877–1939) was the Maharaja of Santosh (a former princely estate in present-day Tangail District, Bangladesh). A passionate patron of Indian football, he served as President of the Indian Football Association (IFA) in Bengal during the 1930s and dedicated his personal wealth to developing indigenous football talents.",significance:"Instigated by the IFA in 1941, the Santosh Trophy is India's premier state-vs-state national football championship. Winning the Santosh Trophy remains one of the highest honors in Indian domestic football history.",icon:"🏆",accentColor:"linear-gradient(135deg, #701a75, #c026d3)"},{id:"vijay-hazare-trophy",trophy:"Vijay Hazare Trophy",sport:"Cricket",category:"Cricket",namesake:"Captain Vijay Samuel Hazare",namesakeCategory:"Sports Legends",yearInstituted:2002,tournament:"Domestic Limited Overs (List A 50-over) Championship",historicalBackground:"Vijay Samuel Hazare (1915–2004) was a legendary Indian batsman and captain. In 1952, Hazare captained India to its historic first-ever Test victory against England at Chennai (Madras). He was the first Indian cricketer to score centuries in both innings of a Test match (against Australia at Adelaide in 1948) and scored 18,740 first-class runs with 60 centuries.",significance:"Renamed in 2002–03 in honor of Vijay Hazare, this tournament brings together all state teams of India for the country's main 50-over domestic List-A championship.",icon:"🏏",accentColor:"linear-gradient(135deg, #0284c7, #38bdf8)"},{id:"deodhar-trophy",trophy:"Deodhar Trophy",sport:"Cricket",category:"Cricket",namesake:"Prof. Dinkar Balwant Deodhar ('Grand Old Man of Indian Cricket')",namesakeCategory:"Sports Legends",yearInstituted:1973,tournament:"Inter-Zonal 50-over Cricket Tournament",historicalBackground:"Prof. Dinkar Balwant Deodhar (1892–1993) was an Indian first-class cricketer and professor of Sanskrit in Pune. Known affectionately as the 'Grand Old Man of Indian Cricket', Deodhar played active first-class cricket into his 50s and scored 4,522 runs. He served as President of the Maharashtra Cricket Association and Vice-President of BCCI.",significance:"Instituted in 1973–74, the Deodhar Trophy is an inter-zonal 50-over competition played between East Zone, West Zone, North Zone, South Zone, and Central Zone.",icon:"🏆",accentColor:"linear-gradient(135deg, #b45309, #f59e0b)"},{id:"duleep-trophy",trophy:"Duleep Trophy",sport:"Cricket",category:"Cricket",namesake:"Kumar Shri Duleepsinhji ('Duleep')",namesakeCategory:"Royalty & Pioneers",yearInstituted:1961,tournament:"First-Class Inter-Zonal Domestic Cricket Championship",historicalBackground:"Kumar Shri Duleepsinhji (1905–1959) was nephew to Jam Saheb Ranjitsinhji and belonged to the royal family of Nawanagar. Duleep played 12 Test matches for England, scoring 995 runs at an average of 58.52, including a debut century against Australia at Lord's in 1930. After independence, he served as High Commissioner of India to Australia and New Zealand.",significance:"Instituted by the BCCI in 1961–62 in memory of Duleepsinhji, the Duleep Trophy tests top state performers in first-class red-ball cricket.",icon:"🏏",accentColor:"linear-gradient(135deg, #4c1d95, #8b5cf6)"},{id:"ck-nayudu-trophy",trophy:"Col. C.K. Nayudu Trophy",sport:"Cricket",category:"Cricket",namesake:"Colonel Cottari Kanakaiya Nayudu (C.K. Nayudu)",namesakeCategory:"Sports Legends",yearInstituted:1974,tournament:"National Under-23 First-Class Cricket Championship",historicalBackground:"Colonel Cottari Kanakaiya Nayudu (1895–1967) was India's very FIRST Test Cricket Captain, leading India in its inaugural Test match against England at Lord's in June 1932. Famed for his massive six-hitting power and commanding military presence, C.K. Nayudu played first-class cricket for 47 years until age 62 and was awarded the Padma Bhushan in 1956.",significance:"The C.K. Nayudu Trophy serves as India's premier Under-23 domestic first-class tournament, bridging youth cricket and the senior Ranji Trophy squad.",icon:"🎖️",accentColor:"linear-gradient(135deg, #15803d, #22c55e)"},{id:"subroto-cup",trophy:"Subroto Cup",sport:"Football",category:"Football",namesake:"Air Marshal Subroto Mukerjee",namesakeCategory:"Military Pioneers",yearInstituted:1960,tournament:"International Inter-School Football Tournament",historicalBackground:"Air Marshal Subroto Mukerjee (1911–1960) was the 'Father of the Indian Air Force' and the first Indian Commander-in-Chief & Chief of the Air Staff of the IAF. An avid sports visionary, Mukerjee conceived the idea of a nationwide school football tournament to encourage fitness, discipline, and grassroots talent discovery.",significance:"Instituted in 1960 by the Subroto Mukerjee Sports Education Society, the Subroto Cup is Asia's largest inter-school football tournament, bringing together school teams from across India and invited foreign nations.",icon:"✈️",accentColor:"linear-gradient(135deg, #0369a1, #0ea5e9)"},{id:"rani-of-jhansi-trophy",trophy:"Rani of Jhansi Trophy",sport:"Cricket",category:"Cricket",namesake:"Rani Lakshmibai of Jhansi",namesakeCategory:"Freedom Fighters",yearInstituted:1974,tournament:"Senior Women's Inter-Zonal Cricket Tournament",historicalBackground:"Rani Lakshmibai (1828–1858), the Queen of the Maratha princely state of Jhansi, was one of the primary leaders of the Indian War of Independence of 1857. She fought courageously against British East India Company forces led by Sir Hugh Rose, becoming a immortal national symbol of female heroism, bravery, and patriotism.",significance:"Instituted by the Women's Cricket Association of India in 1974, the Rani of Jhansi Trophy served as the top inter-zonal domestic tournament for women cricketers, symbolizing strength and courage.",icon:"⚔️",accentColor:"linear-gradient(135deg, #9f1239, #f43f5e)"},{id:"maka-trophy",trophy:"Maulana Abul Kalam Azad (MAKA) Trophy",sport:"Multi-Sport",category:"Multi-Sport",namesake:"Maulana Abul Kalam Azad",namesakeCategory:"Freedom Fighters & Leaders",yearInstituted:1956,tournament:"National Sports Award for Top Performing Indian University",historicalBackground:"Maulana Abul Kalam Azad (1888–1958) was a prominent senior leader of the Indian National Congress, freedom fighter, Islamic scholar, and India's FIRST Minister of Education (1947–1958). He established the Indian Institutes of Technology (IITs), Sahitya Akademi, Sangeet Natak Akademi, and Lalit Kala Akademi, shaping modern Indian education and culture.",significance:"Instituted by the Ministry of Education in 1956–57, the running MAKA Trophy is awarded annually by the President of India to the overall top-performing university in inter-university tournaments, promoting collegiate sports excelence.",icon:"🎓",accentColor:"linear-gradient(135deg, #854d0e, #eab308)"},{id:"bc-roy-trophy",trophy:"Dr. B.C. Roy Trophy",sport:"Football",category:"Football",namesake:"Dr. Bidhan Chandra Roy",namesakeCategory:"Leaders & Statesmen",yearInstituted:1962,tournament:"National Junior (Under-19) Football Championship",historicalBackground:"Dr. Bidhan Chandra Roy (1882–1962) was a legendary physician, freedom fighter, Bharat Ratna recipient, and the second Chief Minister of West Bengal (1948–1962). Respected as the architect of modern West Bengal, National Doctors' Day in India is celebrated on July 1, his birth and death anniversary.",significance:"Instituted by the All India Football Federation (AIFF) in 1962, the Dr. B.C. Roy Trophy is India's national championship for Under-19 state football teams, serving as a primary scouting ground for the Indian National U-19 team.",icon:"🩺",accentColor:"linear-gradient(135deg, #0f766e, #14b8a6)"},{id:"nehru-trophy-boat-race",trophy:"Nehru Trophy Boat Race",sport:"Traditional Boat Racing (Vallam Kali)",category:"Traditional Sports",namesake:"Pandit Jawaharlal Nehru",namesakeCategory:"Prime Ministers & Leaders",yearInstituted:1952,tournament:"Premier Snake Boat Race (Alappuzha, Kerala)",historicalBackground:"Pandit Jawaharlal Nehru (1889–1964) was India's first Prime Minister (1947–1964) and architect of modern industrial India. In December 1952, during his visit to Alappuzha, Kerala, Nehru was so thrilled by an impromptu snake boat (Chundan Vallam) race on Punnamada Lake that he leaped into the winning boat. Upon returning to Delhi, he gifted a silver trophy signed by him.",significance:"Held annually on the second Saturday of August at Punnamada Lake, Alappuzha, the Nehru Trophy Boat Race is India's most famous water sport spectacle, attracting 100-foot-long snake boats rowed by over 100 oarsmen per boat.",icon:"🚣‍♂️",accentColor:"linear-gradient(135deg, #0369a1, #38bdf8)"},{id:"irani-cup",trophy:"Irani Cup (Irani Trophy)",sport:"Cricket",category:"Cricket",namesake:"Zal R. Irani",namesakeCategory:"Sports Administrators",yearInstituted:1959,tournament:"Ranji Champions vs Rest of India Annual Match",historicalBackground:"Zal R. Irani (Z.R. Irani) was a long-serving, influential cricket administrator who served as President and Treasurer of the Board of Control for Cricket in India (BCCI) during the 1920s through 1950s.",significance:"Instituted in 1959–60 to commemorate 25 years of the Ranji Trophy, the Irani Cup is an annual 5-day first-class match played between the reigning Ranji Trophy Champions and the Rest of India team.",icon:"🏏",accentColor:"linear-gradient(135deg, #9a3412, #ea580c)"},{id:"gurmeet-trophy",trophy:"Gurmeet Memorial Hockey Tournament",sport:"Field Hockey",category:"Hockey",namesake:"Brigadier Gurmeet Singh",namesakeCategory:"Military & Sports Pioneers",yearInstituted:1970,tournament:"All-India Gurmeet Memorial Hockey Tournament (Chandigarh)",historicalBackground:"Brigadier Gurmeet Singh was a distinguished Indian Army officer and avid hockey patron who devoted his career to encouraging military and civilian sports talent in North India.",significance:"Hosted annually by the Rock Rovers Hockey Club in Chandigarh, the Gurmeet Memorial Hockey Tournament is one of North India's oldest and most prestigious invitation hockey events.",icon:"🏑",accentColor:"linear-gradient(135deg, #166534, #15803d)"},{id:"nizam-gold-cup",trophy:"Nizam Gold Cup",sport:"Football",category:"Football",namesake:"Mir Osman Ali Khan (7th Nizam of Hyderabad)",namesakeCategory:"Royalty & Patrons",yearInstituted:1955,tournament:"All-India Nizam Gold Cup Football Tournament (Hyderabad)",historicalBackground:"Mir Osman Ali Khan, Asaf Jah VII (1886–1967) was the last ruling Nizam of the Princely State of Hyderabad. Known as one of the wealthiest men in world history, he patronized sports, establishing stadiums, racecourses, and football tournaments in Hyderabad.",significance:"Played in Hyderabad, the Nizam Gold Cup attracted top football clubs across India during Hyderabad's golden era of football (1950s-1970s) when Hyderabad produced legendary Olympic coaches like Syed Abdul Rahim.",icon:"👑",accentColor:"linear-gradient(135deg, #854d0e, #ca8a04)"}];export const matchingPairsData=[{trophy:"Ranji Trophy",namesake:"Maharaja Ranjitsinhji",sport:"Cricket"},{trophy:"Durand Cup",namesake:"Sir Henry Mortimer Durand",sport:"Football"},{trophy:"Santosh Trophy",namesake:"Maharaja Manmatha Nath Roy Chowdhury",sport:"Football"},{trophy:"Khel Ratna Award",namesake:"Major Dhyan Chand",sport:"Multi-Sport"},{trophy:"Vijay Hazare Trophy",namesake:"Captain Vijay Hazare",sport:"Cricket"},{trophy:"Subroto Cup",namesake:"Air Marshal Subroto Mukerjee",sport:"Football"},{trophy:"MAKA Trophy",namesake:"Maulana Abul Kalam Azad",sport:"University Sports"},{trophy:"Nehru Trophy",namesake:"Pandit Jawaharlal Nehru",sport:"Traditional Boat Racing"}];export const trophyQuizQuestions=[{id:1,question:"After which historical figure is India's premier first-class domestic cricket tournament, the Ranji Trophy, named?",options:["Maharaja Ranjit Singh of Punjab","Maharaja Sir Ranjitsinhji of Nawanagar","Ranbir Singh of Jammu","Ranjit Prasad of Bihar"],answer:1,explanation:"The Ranji Trophy was named after Maharaja Sir Ranjitsinhji Vibhaji II ('Ranji'), Jam Saheb of Nawanagar, the first Indian to play Test cricket."},{id:2,question:"Which tournament, founded in 1888 in Shimla, is recognized as Asia's oldest existing football tournament?",options:["Santosh Trophy","Durand Cup","Rovers Cup","I-League"],answer:1,explanation:"The Durand Cup was founded in 1888 by Sir Mortimer Durand, Foreign Secretary of British India, making it Asia's oldest football competition."},{id:3,question:"The Santosh Trophy, India's national inter-state football championship, is named after the Maharaja of which former princely estate?",options:["Santosh (now in Bangladesh)","Cooch Behar","Travancore","Patiala"],answer:0,explanation:"Sir Manmatha Nath Roy Chowdhury was the Maharaja of Santosh (now in Bangladesh) and served as President of the Indian Football Association."},{id:4,question:"Which prime minister gifted a silver trophy after spontaneously jumping into a winning snake boat at Alappuzha, starting a famous boat race?",options:["Lal Bahadur Shastri","Indira Gandhi","Pandit Jawaharlal Nehru","Rajiv Gandhi"],answer:2,explanation:"In December 1952, Jawaharlal Nehru was so thrilled by the snake boat race at Alappuzha, Kerala, that he donated a signed silver trophy, creating the Nehru Trophy Boat Race."},{id:5,question:"India's premier Under-23 first-class cricket tournament is named after which legendary figure who was India's FIRST Test captain in 1932?",options:["Vijay Hazare","Col. C.K. Nayudu","Prof. D.B. Deodhar","Lala Amarnath"],answer:1,explanation:"Colonel Cottari Kanakaiya Nayudu (C.K. Nayudu) was India's first Test captain against England at Lord's in 1932."}];